{"command":"python3 - << 'PY'
import json, subprocess
# Define pattern cells
lead_notes = ["C-4","D-4","E-4","G-4","A-4","G-4","E-4","D-4"]
# Fill rows 0-7
for row in range(8):
    # Lead channel 0
    args = {"pattern":0,"row":row,"channel":0,"note":lead_notes[row],"instrument":1,"volume":64}
    subprocess.run(['ft2','call','pattern_set_cell', json.dumps(args)], check=True)
    # Bass channel 1
    args = {"pattern":0,"row":row,"channel":1,"note":"C-2","instrument":2,"volume":48}
    subprocess.run(['ft2','call','pattern_set_cell', json.dumps(args)], check=True)
    # Kick channel 2 on rows 0 and 4
    if row % 4 == 0:
        args = {"pattern":0,"row":row,"channel":2,"note":"C-3","instrument":3,"volume":64}
        subprocess.run(['ft2','call','pattern_set_cell', json.dumps(args)], check=True)
    # Snare channel 3 on rows 2 and 6
    if row % 4 == 2:
        args = {"pattern":0,"row":row,"channel":3,"note":"C-3","instrument":4,"volume":64}
        subprocess.run(['ft2','call','pattern_set_cell', json.dumps(args)], check=True)
# Set song metadata
song_args = {"bpm":125,"speed":6,"length":1,"loop_start":0,"channels":4}
subprocess.run(['ft2','call','song_set', json.dumps(song_args)], check=True)
# Set order list for position 0 pattern 0
order_args = {"position":0,"pattern":0}
subprocess.run(['ft2','call','order_set', json.dumps(order_args)], check=True)
# Save module
save_args = {"path":"/workspace/submission/tune.xm","format":"xm"}
subprocess.run(['ft2','call','module_save', json.dumps(save_args)], check=True)
print('Module saved')
PY"}
